const uniqueCoreValues = (values) => Array.from(new Set(values.filter(Boolean)));

coreArtworkLibrary.forEach((artwork) => {
  const meta = artworkMetadata[artwork.id] || {};
  const details = coreArtworkFieldDetails[artwork.id] || {};
  const imageCandidates = uniqueCoreValues([
    ...(meta.imageCandidates || []),
    stableArtworkImages[artwork.id],
    artwork.imageUrl
  ]);

  Object.assign(artwork, {
    titleZh: details.titleZh || artwork.title,
    artistZh: details.artistZh || artwork.artist,
    dynastyOrEra: meta.era || artwork.style,
    localImage: stableArtworkImages[artwork.id] || artwork.imageUrl,
    imageCandidates,
    region: details.region || "Europe",
    category: details.category || artwork.style,
    shortIntro: meta.shortIntro || artwork.story,
    visualTags: uniqueCoreValues([...(meta.visualTags || []), ...(artwork.colorMood || [])]),
    themeTags: uniqueCoreValues([...(meta.themeTags || []), ...(artwork.tags || [])]),
    compositionTags: uniqueCoreValues([...(meta.compositionTags || []), ...(artwork.composition || [])]),
    emotionTags: uniqueCoreValues([...(meta.emotionTags || []), ...(artwork.emotion || [])]),
    styleTags: meta.styleTags || [artwork.style],
    bestFor: meta.bestFor || [],
    avoidIf: meta.avoidIf || [],
    detailedIntro: meta.detailedIntro || artwork.story,
    artistLife: meta.artistLife || artwork.artistBio,
    historicalContext: meta.historicalContext || meta.era || artwork.style
  });
});

