function createWorldArtwork(config) {
  const imageBase = "assets/artworks/" + config.id;
  const localImage = config.localImage || imageBase + ".webp";
  const imageCandidates = config.imageCandidates || [
    localImage,
    imageBase + ".jpg",
    config.imageUrl
  ];
  const tags = Array.from(new Set((config.tags || [
    ...(config.themeTags || []),
    ...(config.visualTags || []),
    ...(config.styleTags || []),
    ...(config.emotionTags || [])
  ]).filter(Boolean)));

  return {
    id: config.id,
    title: config.title,
    titleZh: config.titleZh,
    artist: config.artist,
    artistZh: config.artistZh,
    year: config.year,
    dynastyOrEra: config.dynastyOrEra,
    museum: config.museum,
    sourceUrl: config.sourceUrl || "",
    imageUrl: config.imageUrl || "",
    localImage,
    imageCandidates: imageCandidates.filter(Boolean),
    license: config.license || "Offline Demo Metadata / Verify before production use",
    region: config.region,
    category: config.category,
    style: config.style,
    tags,
    triggerEmojis: [],
    colorMood: config.colorMood || ["black", "gray", "white"],
    composition: config.composition || config.compositionTags || [],
    emotion: config.emotion || config.emotionTags || [],
    story: config.story || config.shortIntro,
    artistBio: config.artistBio || config.artistLife,
    shortIntro: config.shortIntro,
    visualTags: config.visualTags,
    themeTags: config.themeTags,
    compositionTags: config.compositionTags,
    emotionTags: config.emotionTags,
    styleTags: config.styleTags,
    bestFor: config.bestFor,
    avoidIf: config.avoidIf,
    detailedIntro: config.detailedIntro,
    artistLife: config.artistLife,
    historicalContext: config.historicalContext,
    funFact: config.funFact,
    rarity: config.rarity
  };
}

