    artistLife: "保罗·塞尚是法国后印象派关键人物，被后来的艺术家视为现代绘画的重要起点。他反复描绘苹果、山体和浴者，把自然对象拆解成体积、色块和结构。",
    historicalContext: "十九世纪末绘画从再现光线转向研究知觉和结构。塞尚的静物证明，普通桌面也能成为现代绘画实验场，并对立体主义和二十世纪艺术产生深远影响。",
